create table public.campaigns (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null check(char_length(trim(title)) between 1 and 160), desired_outcome text not null default '', why text not null default '', life_area text not null, linked_attributes text[] not null default '{}', linked_skill_ids uuid[] not null default '{}', start_date date not null default current_date, target_date date, priority smallint not null default 3 check(priority between 1 and 5), status text not null default 'draft' check(status in ('draft','active','paused','completed','abandoned','archived')), success_criteria text not null default '', weekly_capacity_minutes integer not null default 120 check(weekly_capacity_minutes between 1 and 10080), privacy_level text not null default 'private' check(privacy_level in ('private','allies','public')), completed_at timestamptz, archived_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(target_date is null or target_date >= start_date));
create table public.campaign_milestones (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, title text not null check(char_length(trim(title)) between 1 and 160), description text not null default '', position integer not null check(position >= 0), estimated_minutes integer not null default 30 check(estimated_minutes > 0), status text not null default 'locked' check(status in ('locked','available','in_progress','completed','archived')), completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(campaign_id,position));
create table public.campaign_quests (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete cascade, milestone_id uuid references public.campaign_milestones(id) on delete set null, quest_id uuid not null references public.quests(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, position integer not null default 0 check(position >= 0), created_at timestamptz not null default now(), unique(campaign_id,quest_id));
create table public.quest_dependencies (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, quest_id uuid not null references public.quests(id) on delete cascade, prerequisite_quest_id uuid not null references public.quests(id) on delete cascade, created_at timestamptz not null default now(), check(quest_id <> prerequisite_quest_id), unique(quest_id,prerequisite_quest_id));
create table public.implementation_intentions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, quest_id uuid references public.quests(id) on delete cascade, campaign_id uuid references public.campaigns(id) on delete cascade, situation text not null check(char_length(trim(situation)) between 1 and 240), response text not null check(char_length(trim(response)) between 1 and 240), cue text not null default '', power_up text not null default '', created_at timestamptz not null default now(), check(quest_id is not null or campaign_id is not null));
create table public.campaign_obstacles (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, obstacle text not null, response text not null, status text not null default 'open' check(status in ('open','handled','archived')), created_at timestamptz not null default now());
create table public.boss_encounters (id uuid primary key default gen_random_uuid(), campaign_id uuid not null unique references public.campaigns(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, title text not null, description text not null default '', health_total integer not null check(health_total > 0), health_remaining integer not null check(health_remaining between 0 and health_total), status text not null default 'active' check(status in ('active','defeated','archived')), reward_definition_id uuid references public.item_definitions(id), reward_claimed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.boss_phases (id uuid primary key default gen_random_uuid(), boss_id uuid not null references public.boss_encounters(id) on delete cascade, title text not null, threshold_percent integer not null check(threshold_percent between 0 and 100), position integer not null check(position >= 0), mechanic text not null default '', unique(boss_id,position));
create table public.boss_contributions (id uuid primary key default gen_random_uuid(), boss_id uuid not null references public.boss_encounters(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, source_event_id uuid not null references public.activity_events(id) on delete restrict, amount integer not null check(amount > 0), created_at timestamptz not null default now(), unique(boss_id,source_event_id));
create index campaigns_user_status on public.campaigns(user_id,status); create index campaign_milestones_campaign_position on public.campaign_milestones(campaign_id,position); create index campaign_quests_user on public.campaign_quests(user_id,campaign_id); create index quest_dependencies_quest on public.quest_dependencies(user_id,quest_id); create index boss_contributions_boss on public.boss_contributions(boss_id,created_at);
create trigger campaigns_updated_at before update on public.campaigns for each row execute function public.set_updated_at(); create trigger campaign_milestones_updated_at before update on public.campaign_milestones for each row execute function public.set_updated_at(); create trigger boss_updated_at before update on public.boss_encounters for each row execute function public.set_updated_at();
alter table public.campaigns enable row level security; alter table public.campaign_milestones enable row level security; alter table public.campaign_quests enable row level security; alter table public.quest_dependencies enable row level security; alter table public.implementation_intentions enable row level security; alter table public.campaign_obstacles enable row level security; alter table public.boss_encounters enable row level security; alter table public.boss_phases enable row level security; alter table public.boss_contributions enable row level security;
create policy "own campaigns" on public.campaigns for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own milestones" on public.campaign_milestones for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own campaign quests" on public.campaign_quests for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own dependencies" on public.quest_dependencies for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own intentions" on public.implementation_intentions for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own obstacles" on public.campaign_obstacles for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own bosses" on public.boss_encounters for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own phases" on public.boss_phases for all to authenticated using (exists(select 1 from public.boss_encounters b where b.id=boss_id and b.user_id=(select auth.uid()))) with check (exists(select 1 from public.boss_encounters b where b.id=boss_id and b.user_id=(select auth.uid()))); create policy "own contributions" on public.boss_contributions for select to authenticated using ((select auth.uid())=user_id);
